import{_ as a,o as _,a as c,b as t}from"./app.UgfkfLuP.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"随路ReLU","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_relu"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_relu.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_relu.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"}],"lastUpdated":1791622466000}'),o={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_relu.md"};function r(d,e,l,p,s,i){return _(),c("div",null,[...e[0]||(e[0]=[t('<div><article class="markdown-body"><h1>随路ReLU</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中支持随路ReLU能力，当前支持如下随路ReLU能力。</p><p>随路激活在结果搬出时对数值进行处理，C API入口为<a href="../cube_compute_store/asc_copy_l0c2gm.html">asc_copy_l0c2gm</a>、<a href="../cube_compute_store/asc_copy_l0c2l1.html">asc_copy_l0c2l1</a>。</p><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品还包括<a href="../cube_compute_store/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a>；下表使用Ascend 950PR&amp;950DT系列产品的<a href="../../defs/enum/asc_relu_pre_mode.html">asc_relu_pre_mode</a>名称。</p></div><div data-filter="A3,910b"><p>Atlas A3系列产品和Atlas A2系列产品的<code>relu_pre</code>使用整数参数，需按Atlas A3系列产品和Atlas A2系列产品对应接口的支持范围配置，不能直接套用Ascend 950PR&amp;950DT系列产品专用的配置重载。</p></div><div data-filter="950"><p>下表的<code>asc_relu_pre_mode</code>枚举及其配置接口适用于Ascend 950PR&amp;950DT系列产品。</p><table><thead><tr><th><code>asc_relu_pre_mode</code>枚举值</th><th>编码</th><th>作用及配置</th></tr></thead><tbody><tr><td><code>NONE</code></td><td>0</td><td>不启用激活</td></tr><tr><td><code>NORMAL</code></td><td>1</td><td>Normal ReLU，负半轴系数为0</td></tr><tr><td><code>SCALAR</code></td><td>2</td><td>全矩阵共享激活系数，使用<a href="../cube_store_aux_config/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a>配置</td></tr><tr><td><code>VECTOR</code></td><td>3</td><td>每个N通道独立激活系数，先将系数搬入，再用<a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>配置<code>relu_pre_addr</code></td></tr></tbody></table></div><p>与随路量化组合使用的详细信息请参考<a href="accompanying_quantization_and_relu_scenario_combination.html">随路量化与随路ReLU场景组合</a>。</p><p>Vector激活参数需通过<a href="../cube_compute_load/asc_copy_l12fb.html">asc_copy_l12fb</a>搬入Fixpipe Buffer的激活参数区，再由<a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>配置<code>relu_pre_addr</code>。激活区与量化区独立，配置地址的单位及容量限制参见对应接口。</p><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品搬出接口还提供<code>enable_clip_relu_pre</code>，其使用需结合Normal ReLU和量化模式，不能只设置一个开关而省略配套条件。具体支持组合及参数要求见<a href="../cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm（Ascend 950PR&amp;950DT系列产品）</a>的参数和约束说明，相关Scalar配置接口见<a href="../cube_store_aux_config/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a>和<a href="../cube_store_aux_config/asc_set_l0c_copy_lrelu_alpha.html">asc_set_l0c_copy_lrelu_alpha</a>。</p></div><p>Normal ReLU的完整搬出调用可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/03_c_api/03_matrix_compute/asc_copy_l0c2gm/README.md">asc_copy_l0c2gm样例</a>场景6。</p></article></div>',1)])])}const n=a(o,[["render",r]]);export{m as __pageData,n as default};
